package com.setdef.parakeet

import junit.framework.TestCase

/** BLAKE3 must match what `inko` writes to dep/hash, byte for byte. */
class InkoBlake3Test : TestCase() {
    private fun resource(name: String) = InkoBlake3Test::class.java.getResourceAsStream("/blake3/$name")!!.readBytes()

    fun testKnownVectors() {
        assertEquals("af1349b9f5f9a1a6a0404dea36dcc9499bcb25c9adc112b7cc9a93cae41f3262", InkoBlake3.hex(ByteArray(0)))
        assertEquals("6437b3ac38465133ffb63b75273a8db548c558465d79db03fd359c6cd5bd9d85", InkoBlake3.hex("abc".toByteArray()))
    }

    // Generated by `inko pkg sync`, across BLAKE3's 64-byte block and 1 KiB chunk boundaries.
    fun testMatchesInkoForManifestsOfEverySize() {
        val expected = mapOf(
            20 to "201ee54ee29b038d3d006cad0a76b6d8a4d69ba7026bcf547a1f11efc231b77e",
            63 to "1c923593ccd21416d32c5efc5fcf13c35a2e7562451e9c5769c2cde228d42cfd",
            64 to "50e98eef3774385433e636fccbc767e6555e8afc62d1e08140112d25720fb0c1",
            65 to "da88f1329472c6673cd9830438f03902214c5610da24f36e880e037c757330f4",
            1023 to "e45786fece41d2c030be50f2b3ae1b40c263b97cb8e2591f866acad2a3b16e1b",
            1024 to "f019bc1838f814850bd078fbb43add92ab345aa87019e6feeb06f8008e66cefe",
            1025 to "294fe9c2f3b1a6681634fa208de1beccb7f85e0aba06e0ce55485ed850273274",
            2048 to "abbd3e35ed351f2a4ff27be021034593955019c06a07cfc6c47eac72fdca209b",
            2049 to "e615c9d3adf8438e1dde5859d1a428a1b47b503898201dfc8e3fb8827c090fee",
            3072 to "bcae073a1425691c380b6f5b0fe9c445996efffb24baadc090c92383ca41066b",
            4097 to "0f85dce6444bb389ab7d7f0f3160f29a2dedda42836e132284e30b71a7cb2fde",
            9000 to "66348a3b82451f19194d8507f8a431e0d3b91933df1db30fef4affffb8345c84",
        )
        for ((size, hash) in expected) {
            val bytes = resource("$size.pkg")
            assertEquals("size", size, bytes.size)
            assertEquals("$size bytes", hash, InkoBlake3.hex(bytes))
        }
    }

    // A real project's manifest and the dep/hash inko saved for it (inko-lang/idoc).
    fun testMatchesARealProjectsSavedHash() =
        assertEquals("67ef16ccf852d9cb0120f48294ea0c72908915b68e7fecb924088bb301d7eb31", InkoBlake3.hex(resource("idoc.pkg")))
}
